import heapq


class SeatManager:
    def __init__(self, n: int):
        self.next = 1          # smallest seat never handed out yet: O(1) init
        self.freed = []        # min-heap of seats that were unreserved

    def reserve(self) -> int:
        if self.freed:         # any returned seat is smaller than self.next
            return heapq.heappop(self.freed)    # O(log n)
        seat = self.next
        self.next += 1
        return seat

    def unreserve(self, seatNumber: int) -> None:
        heapq.heappush(self.freed, seatNumber)  # O(log n)
